SELECT UL.LOGIN_ID FROM user_login UL
JOIN user_detail UD ON UL.USER_ID = UD.USER_ID
WHERE UD.USER_NAME = #{name} AND UD.USER_EMAIL = #{email}

SELECT COUNT(*) FROM user_login UL
JOIN user_detail UD ON UL.USER_ID = UD.USER_ID
WHERE UL.login_id = #{loginId} AND UD.USER_EMAIL = #{email}
